mapper.select:
SELECT DATE_FORMAT(o.create_time, '%Y-%m-%d') AS statDate, IFNULL(SUM(oi.price * oi.quantity), 0) AS turnover, COUNT(DISTINCT o.id) AS orderCount FROM order_info o JOIN order_item oi ON oi.order_id = o.id WHERE o.status != 2 AND o.create_time >= DATE_SUB(CURDATE(), INTERVAL #{days} DAY) AND o.stall_id IN
#{id}
GROUP BY statDate ORDER BY statDate ASC

SELECT oi.dish_id AS dishId, oi.dish_name AS dishName, SUM(oi.quantity) AS sold, SUM(oi.price * oi.quantity) AS turnover FROM order_item oi JOIN order_info o ON o.id = oi.order_id WHERE o.status != 2 AND o.create_time >= DATE_SUB(CURDATE(), INTERVAL #{days} DAY) AND o.stall_id IN
#{id}
GROUP BY oi.dish_id, oi.dish_name ORDER BY sold DESC LIMIT #{limit}
